-- Independently attributed GL less subledger difference: invoice, cash, credit, manual/opening.
WITH events AS (
 SELECT 'Invoice posting / amount' category,coalesce((SELECT sum(l.debit_cents-l.credit_cents) FROM journal_entries j JOIN journal_lines l USING(journal_id) WHERE j.source_type='invoice' AND l.account_id='1100' AND j.posting_date<=:as_of AND (:branch=0 OR j.branch_id=:branch)),0)-coalesce((SELECT sum(i.amount_cents) FROM invoices i JOIN orders o USING(order_id) WHERE i.recognition_date<=:as_of AND (:branch=0 OR o.branch_id=:branch)),0) bridge_cents
 UNION ALL SELECT 'Cash applications / timing / branch',coalesce((SELECT sum(l.debit_cents-l.credit_cents) FROM journal_entries j JOIN journal_lines l USING(journal_id) WHERE j.source_type='payment' AND l.account_id='1100' AND j.posting_date<=:as_of AND (:branch=0 OR j.branch_id=:branch)),0)+coalesce((SELECT sum(a.amount_cents) FROM allocations a JOIN invoices i USING(invoice_id) JOIN orders o USING(order_id) WHERE a.allocation_date<=:as_of AND (:branch=0 OR o.branch_id=:branch)),0)
 UNION ALL SELECT 'Credit posting / timing',coalesce((SELECT sum(l.debit_cents-l.credit_cents) FROM journal_entries j JOIN journal_lines l USING(journal_id) WHERE j.source_type='credit' AND l.account_id='1100' AND j.posting_date<=:as_of AND (:branch=0 OR j.branch_id=:branch)),0)+coalesce((SELECT sum(c.amount_cents) FROM credit_memos c JOIN invoices i USING(invoice_id) JOIN orders o USING(order_id) WHERE c.credit_date<=:as_of AND (:branch=0 OR o.branch_id=:branch)),0)
 UNION ALL SELECT 'Manual / opening AR journals',coalesce((SELECT sum(l.debit_cents-l.credit_cents) FROM journal_entries j JOIN journal_lines l USING(journal_id) WHERE j.source_type IN ('manual','opening') AND l.account_id='1100' AND j.posting_date<=:as_of AND (:branch=0 OR j.branch_id=:branch)),0)
) SELECT * FROM events;
